{"code": "fen = "rnbqkbnr/pppp1ppp/8/4p3/4P3/8/PPPP1PPP/RNBQKBNR w KQkq - 0 2"

pos = simulate_move(fen)
candidates = sorted(pos["legal_moves"])
print("candidates:", candidates)

def score(pos):
    if pos["game_over"]:
        w = pos.get("winner")
        if w == "white":
            return 100000
        elif w == "black":
            return -100000
        else:
            return 0
    # material + centralization + check
    s = 0
    sq = pos["squares"]
    # square names
    files = "abcdefgh"
    # build map from square strings
    board = {}
    for r in range(8):
        rank = 8 - r
        for c in range(8):
            f = files[c]
            board[f + str(rank)] = sq[r][c]
    vals = {'P':100,'N':320,'B':330,'R':500,'Q':900,'K':0,
            'p':-100,'n':-320,'b':-330,'r':-500,'q':-900,'k':0}
    central = ['d4','e4','d5','e5']
    for name, piece in board.items():
        if piece == '.':
            continue
        v = vals[piece]
        s += v
        if name in central:
            if piece.isupper():
                s += 12
            else:
                s -= 12
    if pos["turn"] == "black":
        # white is side that just moved? Actually pos["turn"] is side to move after the move.
        # check term: if side to move is in check +25 (if that side is black, minus if white)
        # For white's point of view: if black to move and in check, +25. Let's get in_check.
        if pos.get("in_check"):
            s += 25
    else:
        if pos.get("in_check"):
            s -= 25
    return s

# Precompute scores for candidate positions
best = None
best_score = -10**18
for cand in candidates:
    after = simulate_move(fen, cand)
    if after["game_over"]:
        sc = score(after)
    else:
        # Black replies, minimizer
        replies = after["legal_moves"]
        mn = 10**18
        for rep in replies:
            p2 = simulate_move(after["fen"], rep)
            sc2 = score(p2)
            mn = min(mn, sc2)
        sc = mn
    print(cand, sc)
    if sc > best_score:
        best_score = sc
        best = cand

print("BEST:", best, best_score)
"}

